const TIMELINE = [
  {"id":"tl-monet","artist":"monet","events":[{"year":1840,"when":"1840年","kind":"life","title":"パリで生まれ、ル・アーヴルで育つ","detail":"食料品店を営む家の子として生まれた。","src":[1]},{"year":1862,"when":"1862年","kind":"life","title":"シャルル・グレールの画塾に入る","detail":"この画塾で、ルノワールやバジールらと出会った。","src":[1,2]},{"year":1870,"when":"1870〜1871年","kind":"world","title":"普仏戦争（1870〜1871年）","detail":"フランスとプロイセンの戦争。ナショナル・ギャラリーの紹介ページは、この年代を1870〜71年と記している。","src":[1,2]},{"year":1870,"when":"1870〜1871年","kind":"life","title":"戦争のあいだ、ロンドンへ移る","detail":"ピサロやドービニーも、同じ戦争のあいだにロンドンへ移った。","src":[1,2]},{"year":1871,"when":"1871〜1878年","kind":"life","title":"アルジャントゥイユに住む","detail":"フランスに戻ったあと、1871年から1878年までこの町で暮らした。","src":[1,2]},{"year":1874,"when":"1874年","kind":"work","title":"印象派の展覧会に作品を出す","detail":"メトロポリタン美術館のエッセイによると、このとき出した絵の題名から、画家たちは印象派を名乗った。","src":[1,2]},{"year":1883,"when":"1883年","kind":"life","title":"ジヴェルニーに土地を手に入れる","detail":"パリの北西にある土地。その後は、同じ題材を光の違いで描く連作に力を入れた。","src":[1,2]},{"year":1892,"when":"1892〜1894年","kind":"work","title":"ルーアン大聖堂の連作を描く","detail":"メトロポリタン美術館のエッセイによると、向かいの部屋を借り、光の変化に合わせて何枚も描き進めた。","src":[1,2]},{"year":1926,"when":"1926年","kind":"life","title":"亡くなる","detail":"メトロポリタン美術館のエッセイによると、最後の睡蓮の連作は、死後にパリのオランジュリーへ設置された。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Claude Monet (1840 - 1926)」","url":"https://www.nationalgallery.org.uk/artists/claude-monet","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Claude Monet (1840–1926)」","url":"https://www.metmuseum.org/essays/claude-monet-1840-1926","accessed":"2026-11-08"}]},
  {"id":"tl-vermeer","artist":"vermeer","events":[{"year":1632,"when":"1632年","kind":"life","title":"デルフトで生まれる","detail":"ナショナル・ギャラリーによると、地元の歴史画家ブラーメルの弟子だった可能性がある。","src":[1]},{"year":1650,"when":"1650年代","kind":"work","title":"宗教画や風俗画を描く","detail":"初期の1650年代には、宗教や神話を題材にした絵と、日常を描く風俗画があった。","src":[1,2]},{"year":1653,"when":"1653年","kind":"life","title":"結婚し、画家組合の親方になる","detail":"カトリックの信者だった。同じ年に、デルフトの画家組合の親方になった。","src":[1,2]},{"year":1656,"when":"1656年","kind":"work","title":"『取り持ち女』を描く","detail":"メトロポリタン美術館によると、ドレスデンの美術館にある絵で、画中に自画像らしい人物がいる。","src":[2]},{"year":1672,"when":"1672年までに","kind":"life","title":"お金に困るようになる","detail":"ナショナル・ギャラリーによると、1672年までに経済的に苦しくなっていた。","src":[1,2]},{"year":1672,"when":"1672年","kind":"world","title":"フランス軍がオランダに侵攻する","detail":"ライクスミュージアムの所蔵絵画の解説に、1672年にオランダがフランスに侵攻されたとある。","src":[3]},{"year":1675,"when":"1675年","kind":"life","title":"亡くなる","detail":"ナショナル・ギャラリーによると、妻と多くの子が残された。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Johannes Vermeer」","url":"https://www.nationalgallery.org.uk/artists/johannes-vermeer","accessed":"2026-11-08"},{"name":"メトロポリタン美術館のエッセイ「Johannes Vermeer (1632–1675)」（Department of European Paintings 所属の筆者）","url":"https://www.metmuseum.org/essays/johannes-vermeer-1632-1675","accessed":"2026-11-08"},{"name":"アムステルダム国立美術館「Allegory on the French Invasion of 1672」","url":"https://www.rijksmuseum.nl/en/collection/object/Allegory-on-the-French-Invasion-of-1672--fd3c0c9987ff00e96a60d6cc8b52e42b","accessed":"2026-11-08"}]},
  {"id":"tl-turner","artist":"turner","events":[{"year":1775,"when":"1775年","kind":"life","title":"ロンドンに生まれる","detail":"ロンドンのコヴェント・ガーデンの近くで生まれた。","src":[1,5]},{"year":1789,"when":"1789年","kind":"life","title":"14歳でロイヤル・アカデミーの学校へ","detail":"1789年に、ロイヤル・アカデミーの付属学校に入った。","src":[1,5]},{"year":1796,"when":"1796年","kind":"work","title":"油彩の絵を初めて展覧会に出す","detail":"水彩はすでに1790年からロイヤル・アカデミーに出していた。油彩は1796年から。","src":[1,4]},{"year":1805,"when":"1805年","kind":"world","title":"トラファルガーの戦い","detail":"軍艦テメレールが活躍した戦い。ナショナル・ギャラリーの『ファイティング・テメレール』の解説に出てくる。","src":[2]},{"year":1834,"when":"1834年","kind":"world","title":"国会議事堂が火事になる","detail":"メトロポリタン美術館によると、10月16日に火事が起き、ターナーは船から見て水彩と油彩に描いた。","src":[5]},{"year":1839,"when":"1839年","kind":"work","title":"『ファイティング・テメレール』を展示","detail":"老いた軍艦が解体の場所へテムズ川を曳かれていく場面。ロイヤル・アカデミーで展示された。","src":[2]},{"year":1840,"when":"1840年","kind":"life","title":"批評家ラスキンと出会う","detail":"ラスキンは、ターナーの作品を強く支持する人になった。","src":[1]},{"year":1844,"when":"1844年","kind":"work","title":"『雨、蒸気、速度』を描く","detail":"雨のなか、蒸気機関車が橋を渡ってくる場面。ターナーは産業や技術に関心があった。","src":[3,5]},{"year":1851,"when":"1851年","kind":"life","title":"亡くなる","detail":"作品の多くを国に遺した。絵の大部分は、今はテート・ブリテンにある。","src":[1,5]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Joseph Mallord William Turner (1775 - 1851)」","url":"https://www.nationalgallery.org.uk/artists/joseph-mallord-william-turner","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「The Fighting Temeraire」（NG524）","url":"https://www.nationalgallery.org.uk/paintings/joseph-mallord-william-turner-the-fighting-temeraire","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「Rain, Steam, and Speed - The Great Western Railway」（NG538）","url":"https://www.nationalgallery.org.uk/paintings/joseph-mallord-william-turner-rain-steam-and-speed-the-great-western-railway","accessed":"2026-11-08"},{"name":"テート「Who is J.M.W. Turner?」（Tate Kids）","url":"https://www.tate.org.uk/kids/artists/who-jmw-turner","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Joseph Mallord William Turner (1775–1851)」","url":"https://www.metmuseum.org/essays/joseph-mallord-william-turner-1775-1851","accessed":"2026-11-08"}]},
  {"id":"tl-vangogh","artist":"vangogh","events":[{"year":1853,"when":"1853年","kind":"life","title":"オランダで生まれる","detail":"牧師の息子として生まれた。","src":[1]},{"year":1880,"when":"1880年","kind":"life","title":"画家として活動を始める","detail":"メトロポリタン美術館によると、27歳で画家になると決め、1880年から1890年まで約10年間活動した。","src":[2]},{"year":1886,"when":"1886年","kind":"life","title":"パリでドガやスーラらと出会う","detail":"ナショナル・ギャラリーによると、ドガ、ゴーギャン、スーラらと出会い、使う色が明るくなった。","src":[1,2]},{"year":1888,"when":"1888年","kind":"work","title":"アルルで『ひまわり』の連作を描く","detail":"プロヴァンスのアルルに移り住み、ひまわりの連作を描いた。","src":[1,2]},{"year":1889,"when":"1889年","kind":"life","title":"サン＝レミの療養院に入る","detail":"メトロポリタン美術館によると、1889年5月に入り、約1年をそこで過ごした。","src":[1,2]},{"year":1889,"when":"1889年","kind":"work","title":"糸杉やオリーブ畑を描く","detail":"メトロポリタン美術館によると、療養院の周りの田園を描き、オリーブ畑と糸杉の連作を残した。","src":[1,2]},{"year":1889,"when":"1889年","kind":"world","title":"パリで万国博覧会が開かれる","detail":"","src":[3]},{"year":1890,"when":"1890年","kind":"life","title":"オーヴェル＝シュル＝オワーズに移る","detail":"メトロポリタン美術館によると、5月に療養院を出て、パリにいる弟テオの近くに住んだ。","src":[2]},{"year":1890,"when":"1890年","kind":"life","title":"亡くなる","detail":"メトロポリタン美術館によると、7月に麦畑で自らを撃ち、2日後に亡くなった。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Vincent van Gogh (1853 - 1890)」","url":"https://www.nationalgallery.org.uk/artists/vincent-van-gogh","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Vincent van Gogh (1853–1890)」（Department of European Paintings 所属の筆者）","url":"https://www.metmuseum.org/essays/vincent-van-gogh-1853-1890","accessed":"2026-11-08"},{"name":"オルセー美術館 所蔵品「La Tour Eiffel pendant l\u0027Exposition universelle de 1889. Au premier plan la Seine」","url":"https://www.musee-orsay.fr/en/artworks/la-tour-eiffel-pendant-lexposition-universelle-de-1889-au-premier-plan-la-seine-66016","accessed":"2026-11-08"}]},
  {"id":"tl-boudin","artist":"boudin","events":[{"year":1824,"when":"1824年","kind":"life","title":"ノルマンディーのオンフルールに生まれる","detail":"船長の息子として生まれた。","src":[1,2]},{"year":1855,"when":"1855年以降","kind":"work","title":"ブルターニュへ何度か出かける","detail":"市場や教会、街並みなど、ブルターニュの土地の様子が絵の題材になった。","src":[3]},{"year":1860,"when":"1860年代","kind":"work","title":"トルーヴィルの浜辺を描く","detail":"ドーヴィルやトルーヴィルで、浜辺の絵を多く描いた。夏の行楽客の姿も題材になった。","src":[2,3]},{"year":1871,"when":"1871年","kind":"world","title":"パリ・コミューン","detail":"米国議会図書館によると、民衆主体の政府がパリを3か月のあいだ治めた出来事。","src":[4]},{"year":1874,"when":"1874年","kind":"work","title":"第1回印象派展に参加する","detail":"パリのキャピュシーヌ大通りで開かれた展覧会に作品を出した。","src":[3]},{"year":1884,"when":"1884年","kind":"life","title":"ドーヴィルに住まいを構える","detail":"1855年以降は、ノルマンディーやブルターニュの海岸への旅の合間に、パリかドーヴィルに滞在していた。","src":[3]},{"year":1892,"when":"1892〜1895年","kind":"life","title":"ヴェネツィアへ3度旅する","detail":"晩年、新しい刺激を求めて出かけた。","src":[3]},{"year":1898,"when":"1898年","kind":"life","title":"亡くなる","detail":"","src":[1,2,3]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Eugène Boudin (1824 - 1898)」","url":"https://www.nationalgallery.org.uk/artists/eugene-boudin","accessed":"2026-11-08"},{"name":"ヴィクトリア国立美術館「Tell me about Eugène Boudin」","url":"https://www.ngv.vic.gov.au/essay/tell-me-about-eugene-boudin/","accessed":"2026-11-08"},{"name":"ティッセン＝ボルネミッサ美術館「Boudin, Eugène」","url":"https://www.museothyssen.org/en/collection/artists/boudin-eugene","accessed":"2026-11-08"},{"name":"米国議会図書館「The Paris Commune and the Franco-Prussian War of 1871」","url":"https://guides.loc.gov/women-in-the-french-revolution/revolutions-rebellions/paris-commune-franco-prussian-war-1871","accessed":"2026-11-08"}]},
  {"id":"tl-leonardo","artist":"leonardo","events":[{"year":1452,"when":"1452年","kind":"life","title":"生まれる","detail":"初期の美術の修業は、フィレンツェの彫刻家ヴェロッキオのもとで受けた。","src":[1,2]},{"year":1472,"when":"1472年","kind":"life","title":"画家の同業団体に名を連ねる","detail":"1472年までに、フィレンツェの画家たちの聖ルカ組合に加わっていた。","src":[1,2]},{"year":1474,"when":"1474〜1478年ごろ","kind":"work","title":"『ジネヴラ・デ・ベンチ』を描く","detail":"ワシントンのナショナル・ギャラリー・オブ・アートの作品一覧に載る油彩の板絵で、制作年は1474〜1478年ごろとされる。","src":[2]},{"year":1499,"when":"1499年","kind":"world","title":"フランス軍がミラノに侵攻する","detail":"1499年、フランス軍がミラノを攻めた。","src":[1]},{"year":1499,"when":"1499年","kind":"life","title":"ミラノでの勤めを終える","detail":"ミラノでスフォルツァ公の宮廷に仕える日々は、1499年で終わった。","src":[1,2]},{"year":1513,"when":"1513〜1516年","kind":"life","title":"ローマで3年間を過ごす","detail":"1513年から3年間をローマで過ごし、ジュリアーノ・デ・メディチのために働いた。","src":[1,2]},{"year":1517,"when":"1517年","kind":"life","title":"フランスのクルー城へ移る","detail":"フランス王から「首席画家兼技師」の職を申し出られて受け、アンボワーズ近くの城で余生を送った。","src":[1]},{"year":1519,"when":"1519年","kind":"life","title":"フランスで亡くなる","detail":"1519年5月2日に亡くなり、アンボワーズに葬られた。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Leonardo da Vinci」","url":"https://www.nationalgallery.org.uk/artists/leonardo-da-vinci","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「Leonardo da Vinci」","url":"https://www.nga.gov/artists/1479-leonardo-da-vinci","accessed":"2026-11-08"}]},
  {"id":"tl-degas","artist":"degas","events":[{"year":1834,"when":"1834年","kind":"life","title":"銀行家の長男として生まれる","detail":"父はパリの銀行家で、ドガはその長男だった。","src":[1,2]},{"year":1856,"when":"1856〜1859年","kind":"life","title":"イタリアに3年滞在する","detail":"イタリアですごし、巨匠の絵を模写して学んだ。ルーヴル美術館でも模写をした。","src":[1]},{"year":1865,"when":"1865年","kind":"work","title":"歴史画がサロンに入選する","detail":"メトロポリタン美術館のエッセイによると、この年、サロンが彼の歴史画を受け入れた。","src":[2]},{"year":1870,"when":"1870〜1871年","kind":"world","title":"普仏戦争","detail":"メトロポリタン美術館のエッセイによると、1870〜1871年の戦争で、パリの防衛が行われた。","src":[2]},{"year":1870,"when":"1870〜1871年","kind":"life","title":"パリの防衛に加わる","detail":"メトロポリタン美術館のエッセイによると、普仏戦争のとき、パリを守る任務についた。","src":[2]},{"year":1874,"when":"1874〜1886年","kind":"work","title":"印象派展に6回参加する","detail":"1874年から1886年までの印象派展に6回参加した。創立メンバーの一人でもある。","src":[1,2]},{"year":1878,"when":"1878〜1881年","kind":"work","title":"彫刻『14歳の小さな踊り子』","detail":"彫刻で公に展示したのは、この1点だけだった。","src":[1]},{"year":1917,"when":"1917年","kind":"life","title":"亡くなる","detail":"メトロポリタン美術館のエッセイによると、83歳で亡くなった。フランスの国の宝として称えられた。","src":[1,2]}],"sources":[{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「エドガー・ドガ（Edgar Degas）」","url":"https://www.nga.gov/artists/1219-edgar-degas","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Edgar Degas (1834–1917): Painting and Drawing」（Timeline of Art History）","url":"https://www.metmuseum.org/essays/edgar-degas-1834-1917-painting-and-drawing","accessed":"2026-11-08"}]},
  {"id":"tl-cezanne","artist":"cezanne","events":[{"year":1839,"when":"1839年","kind":"life","title":"プロヴァンスのエクスで生まれる","detail":"少年時代は、裕福な銀行家だった父と、友人ゾラの存在が大きかった。","src":[1,2]},{"year":1860,"when":"1860年","kind":"work","title":"エクスで絵を描きはじめる","detail":"メトロポリタン美術館のエッセイによると、生まれ故郷で描きはじめ、パリでも学んだ。","src":[2]},{"year":1870,"when":"1870年","kind":"world","title":"フランスの第三共和政（〜1940年）","detail":"メトロポリタン美術館のエッセイによると、フランスの第三共和政は1870〜1940年にあたる。","src":[2]},{"year":1874,"when":"1874年","kind":"work","title":"第1回印象派展に出品する","detail":"メトロポリタン美術館のエッセイによると、3点を出品した。印象派の技法とは完全には合っていなかった。","src":[2]},{"year":1880,"when":"1880年代","kind":"work","title":"筆づかいが整ってくる","detail":"この時期、筆のタッチはだんだん規則正しく、まとまりのあるものになっていった。","src":[1]},{"year":1882,"when":"1882年","kind":"work","title":"エクスとレスタックの風景を描く","detail":"メトロポリタン美術館のエッセイによると、この年から、故郷エクスとレスタックの風景画を数多く描いた。","src":[2]},{"year":1890,"when":"1890年","kind":"work","title":"カード遊びの連作を始める","detail":"メトロポリタン美術館のエッセイによると、プロヴァンスの農民がカードで遊ぶ絵を5点の連作として描きはじめた。","src":[2]},{"year":1895,"when":"1895年","kind":"work","title":"パリで初の個展が開かれる","detail":"メトロポリタン美術館のエッセイによると、画商ヴォラールが自分の画廊で開いた。","src":[2]},{"year":1906,"when":"1906年","kind":"life","title":"亡くなる","detail":"","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「ポール・セザンヌ（Paul Cezanne）」","url":"https://www.nationalgallery.org.uk/artists/paul-cezanne","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Paul Cézanne (1839–1906)」（Timeline of Art History、筆者 James Voorhies）","url":"https://www.metmuseum.org/essays/paul-cezanne-1839-1906","accessed":"2026-11-08"}]},
  {"id":"tl-rembrandt","artist":"rembrandt","events":[{"year":1606,"when":"1606年","kind":"life","title":"ライデンで生まれる","detail":"父は製粉業者で、暮らしにゆとりがあった。","src":[1,2]},{"year":1624,"when":"1624年","kind":"life","title":"アムステルダムでラストマンに学ぶ","detail":"ライデンで3年間、地元の画家のもとにいたあと、短期間ピーテル・ラストマンに学んだ。","src":[1]},{"year":1628,"when":"1628年ごろ","kind":"work","title":"初期の自画像を描く","detail":"筆の柄で濡れた絵の具に巻き毛の一部を引っかき、光を背後から当てた自画像。","src":[2]},{"year":1630,"when":"1630年","kind":"work","title":"『エルサレムの滅亡を嘆くエレミヤ』を描く","detail":"先人が描いていない主題にも取り組んだ例として、アムステルダム国立美術館が挙げる作品。","src":[2]},{"year":1631,"when":"1631年ごろ","kind":"life","title":"アムステルダムへ移る","detail":"北ヨーロッパで最も栄えた港町。移ると、たちまち市の第一の肖像画家になった。","src":[1,2]},{"year":1634,"when":"1634年","kind":"life","title":"サスキアと結婚する","detail":"画商ファン・ウイレンブルフの家に下宿し、その家主のいとこのサスキアと出会って結ばれた。","src":[1]},{"year":1650,"when":"1650年代","kind":"world","title":"アムステルダムを大不況が襲う","detail":"1650年代、アムステルダムは大規模な経済不況に見舞われた。","src":[1]},{"year":1656,"when":"1656年","kind":"life","title":"破産して所持品を手放す","detail":"7月に、投獄を避けられる形の破産を申請した。所持品はほとんど手放した。","src":[1,2]},{"year":1669,"when":"1669年","kind":"life","title":"亡くなる","detail":"西教会（ウェステルケルク）で、ヘンドリッキェとティトゥスの隣に葬られた。","src":[1]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Rembrandt (1606 - 1669)」","url":"https://www.nationalgallery.org.uk/artists/rembrandt","accessed":"2026-11-08"},{"name":"アムステルダム国立美術館「Rembrandt van Rijn」（Dutch Masters シリーズ）","url":"https://www.rijksmuseum.nl/en/stories/dutch-masters/story/rembrandt-rijn-10","accessed":"2026-11-08"}]},
  {"id":"tl-manet","artist":"manet","events":[{"year":1832,"when":"1832年","kind":"life","title":"パリの裕福な家に生まれる","detail":"幼いころから、素描や風刺画に才能を見せた。","src":[1,2]},{"year":1850,"when":"1850年","kind":"life","title":"クチュールの工房に入る","detail":"海軍学校に2度入学を断られたあと、アカデミックな画家トマ・クチュールの工房に入った。","src":[2]},{"year":1856,"when":"1856年","kind":"life","title":"画家として独り立ちする","detail":"ほどなく、街の情景や酒場の生活を描いて、批評家の怒りをしばしば買った。","src":[2]},{"year":1863,"when":"1863年","kind":"work","title":"個展を開く","detail":"1863年と1867年に個展を開いた。官展に落選した作品の展覧会でも、名が知られた。","src":[1]},{"year":1865,"when":"1865年","kind":"work","title":"『オランピア』が大騒ぎになる","detail":"サロンに出した裸の高級娼婦の絵が、古典的なヴィーナスのパロディとして前例のない騒ぎを呼んだ。","src":[2]},{"year":1870,"when":"1870年代","kind":"work","title":"印象派に近い風景や街の場面を描く","detail":"モネやルノワールの影響を受けて制作した。それでも印象派と並んで展示することには消極的だった。","src":[1,2]},{"year":1874,"when":"1874年","kind":"world","title":"画家たちの団体が初の展覧会を開く","detail":"ナショナル・ギャラリー・オブ・アートの記事によると、4月15日に開かれた。マネは印象派の展覧会に参加しなかった。","src":[1,3]},{"year":1883,"when":"1883年","kind":"life","title":"亡くなる","detail":"亡くなるまで都会の絵を描き続けた。近代美術の父の一人と認められたのは没後のことだった。","src":[2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Edouard Manet (1832 - 1883)」","url":"https://www.nationalgallery.org.uk/artists/edouard-manet","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「Edouard Manet」","url":"https://www.nga.gov/artists/1506-edouard-manet","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）記事「1874: The Birth of Impressionism」","url":"https://www.nga.gov/stories/articles/1874-birth-impressionism","accessed":"2026-11-08"}]},
  {"id":"tl-renoir","artist":"renoir","events":[{"year":1841,"when":"1841年","kind":"life","title":"リモージュで生まれる","detail":"","src":[1,2]},{"year":1861,"when":"1861〜1862年ごろ","kind":"life","title":"グレールの画塾に入る","detail":"パリでシャルル・グレールの画塾に加わり、モネやシスレーとも出会った。","src":[2]},{"year":1869,"when":"1869年","kind":"work","title":"モネと並んで描く","detail":"モネと並んで描き、このころから明るい色を使いはじめた。","src":[2,3]},{"year":1870,"when":"1870〜1871年","kind":"world","title":"普仏戦争","detail":"メトロポリタン美術館のエッセイによると、1870〜1871年の戦争のなかでパリ包囲戦があった。","src":[4]},{"year":1874,"when":"1874年","kind":"work","title":"第1回印象派展に参加する","detail":"モネやドガらとともに参加した。展覧会は論争を呼んだが、彼の作品は好評だった。","src":[1]},{"year":1876,"when":"1876年","kind":"work","title":"『じょうろを持つ少女』を描く","detail":"軽やかで繊細な作風を示す作品として挙げられている。","src":[1]},{"year":1878,"when":"1878年","kind":"work","title":"印象派から距離を置く","detail":"古典やルネサンスの美術に学ぶ、新しい方向を探った。","src":[1,3]},{"year":1881,"when":"1881年","kind":"life","title":"イタリアを訪れる","detail":"ロンドン・ナショナル・ギャラリーによると、この訪問のあと、作風は線を重んじる古典的なものになった。","src":[2,3]},{"year":1919,"when":"1919年","kind":"life","title":"亡くなる","detail":"78歳で亡くなった。","src":[1]}],"sources":[{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「オーギュスト・ルノワール（Auguste Renoir）」","url":"https://www.nga.gov/artists/1823-auguste-renoir","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「ピエール＝オーギュスト・ルノワール（Pierre-Auguste Renoir）」","url":"https://www.nationalgallery.org.uk/artists/pierre-auguste-renoir","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Auguste Renoir (1841–1919)」（Timeline of Art History）","url":"https://www.metmuseum.org/essays/auguste-renoir-1841-1919","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Impressionism: Art and Modernity」（Timeline of Art History）","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity","accessed":"2026-11-08"}]},
  {"id":"tl-raphael","artist":"raphael","events":[{"year":1483,"when":"1483年","kind":"life","title":"ウルビーノで生まれる","detail":"父ジョヴァンニ・サンティは宮廷画家だった。","src":[1,2]},{"year":1500,"when":"1500年","kind":"life","title":"独立した画家になる","detail":"ナショナル・ギャラリーによると、1500年から1508年まで中部イタリア各地で仕事をした。","src":[1]},{"year":1503,"when":"1503年","kind":"world","title":"ユリウス2世が教皇になる","detail":"バチカン美術館によると、在位は1503年から1513年。","src":[3]},{"year":1504,"when":"1504年末","kind":"life","title":"フィレンツェへ移る","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、レオナルドの仕事の評判に引かれての移住。","src":[2]},{"year":1505,"when":"1505年ごろ","kind":"work","title":"『スモール・カウパー・マドンナ』","detail":"ワシントンのナショナル・ギャラリー・オブ・アートが所蔵する、聖母（マドンナ）を描いた板絵。1505年ごろの作。","src":[4]},{"year":1508,"when":"1508年","kind":"life","title":"教皇に呼ばれてローマへ","detail":"25歳のとき教皇ユリウス2世に呼ばれ、教皇の居室の改装を手伝うことになった。","src":[1,2]},{"year":1508,"when":"1508〜1511年","kind":"work","title":"署名の間の壁画（『アテネの学堂』）","detail":"バチカン美術館によると、この部屋の壁画は1508〜1511年に描かれ、『アテネの学堂』は哲学を表す。","src":[3]},{"year":1514,"when":"1514年","kind":"life","title":"サン・ピエトロ大聖堂の建築責任者に","detail":"ナショナル・ギャラリーによると、ブラマンテの死を受けて任じられた。","src":[1]},{"year":1520,"when":"1520年","kind":"life","title":"37歳で亡くなる","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、教皇の命でパンテオンに葬られた。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Raphael」","url":"https://www.nationalgallery.org.uk/artists/raphael","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「Raphael」","url":"https://www.nga.gov/artists/1818-raphael","accessed":"2026-11-08"},{"name":"バチカン美術館「Room of the Segnatura」「School of Athens」","url":"https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/stanze-di-raffaello/stanza-della-segnatura/stanza-della-segnatura.html","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「The Small Cowper Madonna」","url":"https://www.nga.gov/artworks/1196-small-cowper-madonna","accessed":"2026-11-08"}]},
  {"id":"tl-gauguin","artist":"gauguin","events":[{"year":1848,"when":"1848年","kind":"life","title":"パリで生まれる","detail":"","src":[1]},{"year":1871,"when":"1871年","kind":"life","title":"株式仲買人になる","detail":"商船員として働いたあと、株式仲買人になり、絵も描くようになった。","src":[1]},{"year":1879,"when":"1879年","kind":"work","title":"ピサロと制作をともにする","detail":"ナショナル・ギャラリーによると、初期の作品はピサロの影響を受けた。ともに制作したのは1879年と1881年。","src":[1,2]},{"year":1888,"when":"1888年","kind":"life","title":"アルルでゴッホと制作する","detail":"ナショナル・ギャラリーによると、アルルでゴッホとごく短い期間いっしょに制作した。","src":[1,2]},{"year":1889,"when":"1889年","kind":"world","title":"万国博覧会が開かれる","detail":"メトロポリタン美術館のエッセイによると、ゴーガンは、この博覧会の敷地内にあるカフェで開かれた、自分と仲間の作品の展覧会づくりに加わった。","src":[2]},{"year":1891,"when":"1891年","kind":"life","title":"タヒチへ旅立つ","detail":"パリを離れてタヒチへ。ナショナル・ギャラリーによると、有名な作品の多くはタヒチで生まれた。","src":[1,2]},{"year":1897,"when":"1897〜1898年","kind":"work","title":"『我々はどこから来たのか…』を描く","detail":"ボストン美術館によると、生涯で最大の絵。壁画のように見せるつもりで描き、1898年にパリの画廊で公開された。","src":[3,2]},{"year":1901,"when":"1901年","kind":"life","title":"マルキーズ諸島へ移る","detail":"ナショナル・ギャラリーによると、マルキーズ諸島に移った。メトロポリタン美術館のエッセイでは、島の名はヒバ・オア島。","src":[1,2]},{"year":1903,"when":"1903年","kind":"life","title":"マルキーズ諸島で亡くなる","detail":"メトロポリタン美術館のエッセイによると、ヒバ・オア島で亡くなった。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Paul Gauguin」","url":"https://www.nationalgallery.org.uk/artists/paul-gauguin","accessed":"2026-11-08"},{"name":"メトロポリタン美術館のサイト「Paul Gauguin (1848–1903)」（Timeline of Art History、筆者 Cindy Kang、ニューヨーク大学美術研究所）","url":"https://www.metmuseum.org/essays/paul-gauguin-1848-1903","accessed":"2026-11-08"},{"name":"ボストン美術館「Where Do We Come From? What Are We? Where Are We Going?」","url":"https://collections.mfa.org/objects/32558","accessed":"2026-11-08"}]},
  {"id":"tl-botticelli","artist":"botticelli","events":[{"year":1445,"when":"1445年ごろ","kind":"life","title":"なめし皮職人の子として生まれる","detail":"本名はアレッサンドロ・ディ・マリアーノ・フィリペーピ。ボッティチェリは小さな酒樽を意味する語からついたあだ名。","src":[1,2]},{"year":1470,"when":"1470年までに","kind":"life","title":"自分の工房を持つ","detail":"1470年までには、自分の工房を構えていた。","src":[1]},{"year":1472,"when":"1472年","kind":"life","title":"画家の信心会に入る","detail":"フィレンツェの画家たちの団体「サン・ルカ信心会」に加わった。","src":[1]},{"year":1480,"when":"1480年ごろ","kind":"work","title":"『春（プリマヴェーラ）』を描く","detail":"神話の登場人物9人を描いた絵で、ウフィツィ美術館が所蔵している。","src":[3]},{"year":1481,"when":"1481年","kind":"life","title":"教皇に呼ばれてローマへ行く","detail":"完成したばかりのシスティーナ礼拝堂の壁を飾る仕事で、モーセの生涯などの場面を描いた。","src":[1]},{"year":1485,"when":"1485年ごろ","kind":"work","title":"『ヴィーナスの誕生』を描く","detail":"愛と美の女神が大きな貝殻の上に立ち、キプロス島に着く場面。ウフィツィ美術館が所蔵している。","src":[2]},{"year":1490,"when":"1490年代","kind":"world","title":"メディチ家がフィレンツェを追われる","detail":"ナショナル・ギャラリーによると、1490年代はメディチ家の追放に加え、侵攻や疫病でイタリアの平和が乱れた時代だった。","src":[1]},{"year":1510,"when":"1510年","kind":"life","title":"亡くなる","detail":"ナショナル・ギャラリーもウフィツィ美術館も、没年を1510年としている。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Sandro Botticelli (about 1445 - 1510)」","url":"https://www.nationalgallery.org.uk/artists/sandro-botticelli","accessed":"2026-11-08"},{"name":"ウフィツィ美術館「Birth of Venus」","url":"https://www.uffizi.it/en/artworks/birth-of-venus","accessed":"2026-11-08"},{"name":"ウフィツィ美術館「Spring」","url":"https://www.uffizi.it/en/artworks/botticelli-spring","accessed":"2026-11-08"}]},
  {"id":"tl-klimt","artist":"klimt","events":[{"year":1862,"when":"1862年","kind":"life","title":"ウィーンで生まれる","detail":"父は版画を彫る職人で、本人も兄弟のエルンストもウィーンの応用美術学校に通った。","src":[1,4]},{"year":1892,"when":"1892年","kind":"life","title":"父と兄弟が相次いで亡くなる","detail":"父とエルンストを数か月のうちに失ったこの出来事は、作風が大きく変わる長い危機の始まりとなった。","src":[1]},{"year":1897,"when":"1897年","kind":"life","title":"分離派を結成して初代会長になる","detail":"キュンストラーハウスを去った仲間の芸術家たちとウィーン分離派を作った。保守的になっていくウィーンの美術界への反発だった。","src":[1,5]},{"year":1901,"when":"1901年","kind":"work","title":"『ユディト』を描く","detail":"ベルヴェデーレ宮殿美術館の解説は、この絵を「金の時代」のはじまりを示す作品とみなしている。","src":[1,3]},{"year":1903,"when":"1903年","kind":"world","title":"ウィーン工房が設立される","detail":"テートの用語集のウィーン分離派の項目に、この年、デザイン会社ウィーン工房が設立されたと書かれている。","src":[5]},{"year":1908,"when":"1908年","kind":"work","title":"『接吻』を初めて展覧会に出す","detail":"ベルヴェデーレの解説では、この年のクンストシャウ・ウィーンで『恋人たち』の題で展示された。","src":[2]},{"year":1918,"when":"1918年","kind":"life","title":"ウィーンで亡くなる","detail":"生まれ育ったウィーンで亡くなった。","src":[1,4]}],"sources":[{"name":"ベルヴェデーレ宮殿美術館「Who Was Gustav Klimt?」","url":"https://www.belvedere.at/en/stories/who-was-gustav-klimt","accessed":"2026-11-08"},{"name":"ベルヴェデーレ宮殿美術館 コレクション「Der Kuss (Liebespaar)」","url":"https://sammlung.belvedere.at/objects/6678/the-kiss-lovers","accessed":"2026-11-08"},{"name":"ベルヴェデーレ宮殿美術館 コレクション「Judith」","url":"https://sammlung.belvedere.at/objects/3492/judith","accessed":"2026-11-08"},{"name":"ベルヴェデーレ宮殿美術館 コレクション「Gustav Klimt」（作家ページ）","url":"https://sammlung.belvedere.at/people/1064/gustav-klimt","accessed":"2026-11-08"},{"name":"テート「Secession」（美術用語集）","url":"https://www.tate.org.uk/art/art-terms/secession","accessed":"2026-11-08"}]},
  {"id":"tl-millet","artist":"millet","events":[{"year":1814,"when":"1814年","kind":"life","title":"マンシュ県で生まれる","detail":"オルセー美術館の人物欄では、現在のグレヴィル＝アーグ（マンシュ県）の生まれとされている。","src":[2,3]},{"year":1848,"when":"1848年","kind":"work","title":"サロンに『箕をふるう人』を出す","detail":"神話を離れて農民を主役にした作品で、ミレーが農民の絵に進む転機になった。ナショナル・ギャラリーは最初の人気作とする。","src":[1,3]},{"year":1849,"when":"1849年","kind":"life","title":"バルビゾンに腰を据える","detail":"メトロポリタン美術館によると、パリ郊外のバルビゾン村に腰を据え、農村の場面を描くことに打ち込んだ。","src":[3,5]},{"year":1850,"when":"1850年","kind":"work","title":"サロンに『種をまく人』を出す","detail":"ボストン美術館によると、この絵が1850年のサロンに出て、ミレーは一気に有名になった。","src":[4]},{"year":1857,"when":"1857年","kind":"work","title":"『落穂拾い』を描く","detail":"オルセー美術館は、この絵を10年にわたる落穂拾いの主題の探究の成果だとしている。","src":[1,6]},{"year":1857,"when":"1857〜1859年","kind":"work","title":"『アンジェラス（晩鐘）』を描く","detail":"畑仕事の手を止めて祈る農民の男女の絵。オルセー美術館が所蔵している。","src":[1]},{"year":1870,"when":"1870〜1871年","kind":"world","title":"普仏戦争","detail":"フランスとプロイセンの戦争。オルセー美術館の記事が、ミレーの避難先の話の中で触れている出来事。","src":[1,7]},{"year":1870,"when":"1870〜1871年","kind":"life","title":"戦争を避けて故郷の地方へ移る","detail":"家族とともに、生まれた地方へ避難した。","src":[1]},{"year":1875,"when":"1875年","kind":"life","title":"バルビゾンで亡くなる","detail":"バルビゾンで亡くなった。","src":[2,3]}],"sources":[{"name":"オルセー美術館「150 ans de la mort de Jean-François Millet, le peintre de la vie paysanne」","url":"https://www.musee-orsay.fr/en/node/284870","accessed":"2026-11-08"},{"name":"オルセー美術館「Jean-François Millet (35867)」","url":"https://www.musee-orsay.fr/en/ressources/artists-personalities-catalog/jean-francois-millet-35867","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「Jean-François Millet (1814 - 1875)」","url":"https://www.nationalgallery.org.uk/artists/jean-francois-millet","accessed":"2026-11-08"},{"name":"ボストン美術館「The Sower」","url":"https://collections.mfa.org/objects/31601/the-sower","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「A Shepherdess with Her Flock」","url":"https://www.metmuseum.org/art/collection/search/337784","accessed":"2026-11-08"},{"name":"オルセー美術館「Des glaneuses」","url":"https://www.musee-orsay.fr/en/artworks/des-glaneuses-342","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「Claude Monet (1840 - 1926)」（普仏戦争の年）","url":"https://www.nationalgallery.org.uk/artists/claude-monet","accessed":"2026-11-08"}]},
  {"id":"tl-rubens","artist":"rubens","events":[{"year":1577,"when":"1577年","kind":"life","title":"ドイツのジーゲンで生まれる","detail":"10歳のころからはアントワープで暮らし、学校に通った。","src":[1]},{"year":1600,"when":"1600年","kind":"life","title":"イタリアへ向かう","detail":"メトロポリタン美術館によると、1600年にイタリアへ行き、8年間とどまった。","src":[2,1]},{"year":1608,"when":"1608年","kind":"life","title":"アントワープへ戻る","detail":"ナショナル・ギャラリーによると、母が危篤との知らせで急ぎ出発したが、着いた時にはすでに亡くなっていた。","src":[1,2]},{"year":1609,"when":"1609年","kind":"life","title":"宮廷画家に任じられる","detail":"ネーデルラントを治める大公アルブレヒトと妃イサベラの宮廷画家になった。33歳のとき。","src":[1,2]},{"year":1609,"when":"1609〜1610年","kind":"work","title":"大聖堂にある祭壇画（十字架を立てる場面）","detail":"アントワープ大聖堂の公式サイトによると1609〜1610年の作で、今もこの大聖堂にある。","src":[4,2]},{"year":1611,"when":"1611〜1614年","kind":"work","title":"『十字架からの降下』を描く","detail":"大聖堂の公式サイトによると1611〜1614年の三連祭壇画。中央にキリストの遺体を十字架からおろす場面がある。","src":[3,2]},{"year":1621,"when":"1621年","kind":"world","title":"休戦が終わり、大公が亡くなる","detail":"ナショナル・ギャラリーによると、オランダとスペインの12年間の休戦が1621年に終わり、大公アルブレヒトも亡くなった。","src":[1]},{"year":1625,"when":"1625年","kind":"world","title":"ペストがアントワープに及ぶ","detail":"ナショナル・ギャラリーによると、ルーベンスは家族をブリュッセルに移し、最悪の時期が過ぎるまでそこで過ごした。","src":[1]},{"year":1630,"when":"1630年","kind":"life","title":"53歳で再婚する","detail":"相手は商家の16歳の娘エレーヌ・フールマン。","src":[1,2]},{"year":1640,"when":"1640年","kind":"life","title":"亡くなる","detail":"5月に亡くなった。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Peter Paul Rubens」","url":"https://www.nationalgallery.org.uk/artists/peter-paul-rubens","accessed":"2026-11-08"},{"name":"メトロポリタン美術館のエッセイ「Peter Paul Rubens (1577–1640) and Anthony van Dyck (1599–1641): Paintings」（Department of European Paintings 所属の筆者）","url":"https://www.metmuseum.org/essays/peter-paul-rubens-1577-1640-and-anthony-van-dyck-1599-1641-paintings","accessed":"2026-11-08"},{"name":"アントワープ大聖堂（De Kathedraal）「The Descent from the Cross」","url":"https://www.dekathedraal.be/en/rubens-descent-cross","accessed":"2026-11-08"},{"name":"アントワープ大聖堂（De Kathedraal）「The Elevation of the Cross」","url":"https://www.dekathedraal.be/en/rubens-elevation-cross","accessed":"2026-11-08"}]},
  {"id":"tl-lautrec","artist":"lautrec","events":[{"year":1864,"when":"1864年","kind":"life","title":"アルビで生まれる","detail":"裕福な地主の家に生まれた。","src":[1]},{"year":1878,"when":"1878〜1879年","kind":"life","title":"両脚を骨折して療養する","detail":"1878年に左、翌年に右の大腿骨を折り、長い療養のあいだに素描に関心を持った。","src":[1]},{"year":1882,"when":"1882年","kind":"life","title":"パリへ出て画家の修業を始める","detail":"レオン・ボナのアトリエで学び、数年後にはフェルナン・コルモンのもとで学んだ。","src":[1]},{"year":1884,"when":"1884年","kind":"life","title":"モンマルトルに自分の仕事場を構える","detail":"芸術家がよく訪れる地区。近所のカフェ・サーカス・キャバレーに通い、作品の題材にした。","src":[1]},{"year":1886,"when":"1886年","kind":"work","title":"キャバレーに絵が飾られはじめる","detail":"1886年から、彼の絵がキャバレー「ル・ミルリトン」にずっと掛けられていた。","src":[1]},{"year":1889,"when":"1889年","kind":"world","title":"ムーラン・ルージュが開場する","detail":"開場のとき、ロートレックのサーカスの絵（1888年）が展示されていた。","src":[1]},{"year":1891,"when":"1891年","kind":"work","title":"ムーラン・ルージュのポスターを手がける","detail":"最初のポスターで、最も有名とされる。同年12月には3000枚がパリの街に貼られた。","src":[3,4]},{"year":1901,"when":"1901年","kind":"life","title":"亡くなる","detail":"脳卒中で倒れ、37歳になる前に亡くなった。","src":[1,2]}],"sources":[{"name":"ティッセン＝ボルネミッサ美術館「Henri de Toulouse-Lautrec」","url":"https://www.museothyssen.org/en/collection/artists/toulouse-lautrec-henri","accessed":"2026-11-08"},{"name":"オルセー美術館「Henri de Toulouse Lautrec. Resolutely Modern」","url":"https://www.musee-orsay.fr/en/program/whats-on/exhibitions/henri-de-toulouse-lautrec-resolutely-modern","accessed":"2026-11-08"},{"name":"ゴッホ美術館「Moulin Rouge, La Goulue, poster for the Dance Hall Le Moulin Rouge」","url":"https://www.vangoghmuseum.nl/en/collection/p0914N1996","accessed":"2026-11-08"},{"name":"アムステルダム国立美術館「Poster for ‘Le Moulin Rouge’」","url":"https://www.rijksmuseum.nl/en/collection/RP-P-1954-57","accessed":"2026-11-08"}]},
  {"id":"tl-delacroix","artist":"delacroix","events":[{"year":1798,"when":"1798年","kind":"life","title":"シャラントン＝サン＝モーリスで生まれる","detail":"ヴァル＝ド＝マルヌ県の町で生まれた。","src":[3,1]},{"year":1816,"when":"1816〜1823年ごろ","kind":"life","title":"ピエール・ゲランに学ぶ","detail":"新古典主義の画家ゲランに師事した。ジェリコーもゲランに教わっている。","src":[1]},{"year":1822,"when":"1822年","kind":"work","title":"サロンに初めて出品する","detail":"1822年に初めてサロンに出品した。","src":[1]},{"year":1825,"when":"1825年","kind":"life","title":"イギリスを訪れる","detail":"イギリス絵画を高く評価していた。","src":[1]},{"year":1830,"when":"1830年","kind":"world","title":"パリで七月の蜂起が起こる","detail":"パリの人々が3日間、出版の自由などを守ろうと街頭に出た。","src":[2,1]},{"year":1830,"when":"1830年","kind":"work","title":"『民衆を導く自由』を描く","detail":"題材は1789年の革命ではなく1830年7月の蜂起。本人は「現代の主題、バリケード」と呼んだ。","src":[2,3]},{"year":1832,"when":"1832年","kind":"life","title":"スペイン・モロッコ・アルジェを旅する","detail":"1832年にスペイン、モロッコ、アルジェを訪れた。","src":[1]},{"year":1833,"when":"1833年","kind":"work","title":"公的な注文が始まる","detail":"1833年のパレ・ブルボンの装飾を皮切りに、公的な注文が長く続いた。","src":[1]},{"year":1863,"when":"1863年","kind":"life","title":"パリで亡くなる","detail":"ルーヴル美術館の目録では、1863年にパリで亡くなったと記されている。","src":[3,1]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Eugène Delacroix (1798 - 1863)」","url":"https://www.nationalgallery.org.uk/artists/eugene-delacroix","accessed":"2026-11-08"},{"name":"ルーヴル美術館「Romanticism, topicality, sensuality…」","url":"https://www.louvre.fr/en/explore/visitor-trails/the-louvre-s-masterpieces/romanticism-topicality-sensuality","accessed":"2026-11-08"},{"name":"ルーヴル美術館コレクション「Le 28 juillet 1830. La Liberté guidant le peuple」","url":"https://collections.louvre.fr/en/ark:/53355/cl010065872","accessed":"2026-11-08"}]},
  {"id":"tl-courbet","artist":"courbet","events":[{"year":1819,"when":"1819年","kind":"life","title":"オルナンで生まれる","detail":"フランス東部のオルナンに生まれた。","src":[1,2]},{"year":1840,"when":"1840年","kind":"life","title":"パリでルーヴルの絵を研究する","detail":"1840年からパリで、特にオランダとヴェネツィアの絵をルーヴル美術館で学んだ。","src":[1]},{"year":1844,"when":"1844年","kind":"work","title":"サロンに出品する","detail":"1844年にサロンに出品した。","src":[1]},{"year":1849,"when":"1849〜1850年","kind":"work","title":"『オルナンの埋葬』を描く","detail":"村人を等身大で、理想化せずに描いた大作。批評家からは激しい批判を受けた。","src":[3]},{"year":1854,"when":"1854〜1855年","kind":"work","title":"『画家のアトリエ』を描く","detail":"右に友人や芸術愛好家、左に日常の世界が並び、中央に画家自身がいる巨大な作品。","src":[2]},{"year":1855,"when":"1855年","kind":"world","title":"1855年の万国博覧会","detail":"クールベの『画家のアトリエ』は、この万国博覧会への出品を断られた。","src":[1,2]},{"year":1855,"when":"1855年","kind":"work","title":"自費で「レアリスム館」を建てる","detail":"万博の公式の催しとは別に自分の展覧会を開き、『オルナンの埋葬』なども展示した。","src":[1,2]},{"year":1871,"when":"1871年","kind":"world","title":"パリ・コミューンが成立する","detail":"1871年3月にコミューンが作られた。","src":[4]},{"year":1871,"when":"1871年","kind":"life","title":"コミューンの評議会に選ばれる","detail":"教育を担当する代表や、美術家連盟の会長にもなった。","src":[4,1]},{"year":1877,"when":"1877年","kind":"life","title":"亡命先のスイスで亡くなる","detail":"晩年はスイスに亡命して過ごし、スイスのラ・トゥール＝ド＝ペイで亡くなった。","src":[1,2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Gustave Courbet (1819 - 1877)」","url":"https://www.nationalgallery.org.uk/artists/gustave-courbet","accessed":"2026-11-08"},{"name":"オルセー美術館「L\u0027Atelier du peintre - Gustave Courbet」","url":"https://www.musee-orsay.fr/en/artworks/latelier-du-peintre-927","accessed":"2026-11-08"},{"name":"オルセー美術館「Un enterrement à Ornans - Gustave Courbet」","url":"https://www.musee-orsay.fr/en/artworks/un-enterrement-ornans-924","accessed":"2026-11-08"},{"name":"オルセー美術館「Courbet and the Commune」","url":"https://www.musee-orsay.fr/en/program/whats-on/exhibitions/presentation/courbet-and-commune","accessed":"2026-11-08"}]},
  {"id":"tl-seurat","artist":"seurat","events":[{"year":1859,"when":"1859年","kind":"life","title":"パリで生まれる","detail":"オルセー美術館の記録では、スーラは1859年にパリで生まれた。","src":[1]},{"year":1884,"when":"1884年","kind":"work","title":"『アニエールの水浴者たち』を描く","detail":"初めての大作。春のサロン（官立の展覧会）に出すつもりだったが、落選した。","src":[2]},{"year":1884,"when":"1884〜1886年","kind":"work","title":"『グランド・ジャット島の日曜日』を制作","detail":"1884〜86年の作品。ロンドン・ナショナル・ギャラリーは、最初期の習作の1つを現地で描いた可能性が高いとする。","src":[3]},{"year":1886,"when":"1886年","kind":"work","title":"最後の印象派展に出品","detail":"メトロポリタン美術館によると、『グランド・ジャット島の日曜日』をこの第8回印象派展で初めて見せた。","src":[4,5]},{"year":1889,"when":"1889年","kind":"world","title":"パリで万国博覧会が開かれる","detail":"","src":[6]},{"year":1891,"when":"1891年","kind":"work","title":"未完の『サーカス』を出品","detail":"未完のまま、1891年のアンデパンダン展に出された。","src":[1]},{"year":1891,"when":"1891年","kind":"life","title":"パリで亡くなる","detail":"オルセー美術館によると、アンデパンダン展が始まった数日後に亡くなった。出身地もパリ。","src":[1]}],"sources":[{"name":"オルセー美術館「Le Cirque（サーカス）」","url":"https://www.musee-orsay.fr/en/artworks/le-cirque-542","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「Bathers at Asnières」","url":"https://www.nationalgallery.org.uk/paintings/georges-seurat-bathers-at-asnieres","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「Study for \u0027La Grande Jatte\u0027」","url":"https://www.nationalgallery.org.uk/paintings/georges-seurat-study-for-la-grande-jatte","accessed":"2026-11-08"},{"name":"ワシントン・ナショナル・ギャラリー「The Lighthouse at Honfleur」","url":"https://www.nga.gov/artworks/61383-lighthouse-honfleur","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Georges Seurat (1859–1891) and Neo-Impressionism」","url":"https://www.metmuseum.org/essays/georges-seurat-1859-1891-and-neo-impressionism","accessed":"2026-11-08"},{"name":"オルセー美術館 所蔵品「La Tour Eiffel pendant l\u0027Exposition universelle de 1889. Au premier plan la Seine」","url":"https://www.musee-orsay.fr/en/artworks/la-tour-eiffel-pendant-lexposition-universelle-de-1889-au-premier-plan-la-seine-66016","accessed":"2026-11-08"}]},
  {"id":"tl-goya","artist":"goya","events":[{"year":1746,"when":"1746年","kind":"life","title":"フエンデトドスで生まれる","detail":"サラゴサの近くにあるフエンデトドスの生まれ。","src":[1,2]},{"year":1786,"when":"1786年","kind":"life","title":"カルロス3世付きの宮廷画家になる","detail":"スペイン王カルロス3世に仕える宮廷画家に任命された。","src":[1]},{"year":1792,"when":"1792年","kind":"life","title":"重い病気のあと耳が聞こえなくなる","detail":"1792年、重い病気のあとに耳が聞こえなくなった。","src":[1]},{"year":1799,"when":"1799年","kind":"life","title":"カルロス4世の首席宮廷画家になる","detail":"1799年に、カルロス4世の首席の宮廷画家へ昇進した。","src":[1,2]},{"year":1799,"when":"1799年","kind":"work","title":"連作版画『カプリチョス』を出版","detail":"メトロポリタン美術館によると、魔女や幽霊が登場する寓意的なエッチング80点を完成させ、出版した。","src":[2]},{"year":1808,"when":"1808年","kind":"world","title":"ナポレオン軍がスペインに侵入","detail":"メトロポリタン美術館によると、侵攻はフランスの占領に至り、ナポレオンの兄弟ジョゼフがスペイン王位についた。","src":[2]},{"year":1820,"when":"1820〜1823年","kind":"work","title":"小さな田舎の家で『黒い絵』を描く","detail":"メトロポリタン美術館によると、『聾者の家』と呼ばれる小さな田舎の家で、私的なフレスコ画の連作を仕上げた。","src":[2]},{"year":1824,"when":"1824年","kind":"life","title":"ボルドーに移る","detail":"1824年にボルドーへ移った。","src":[1,2]},{"year":1828,"when":"1828年","kind":"life","title":"ボルドーで亡くなる","detail":"ロンドン・ナショナル・ギャラリーによると、亡くなった場所はボルドー。","src":[1]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Francisco de Goya」","url":"https://www.nationalgallery.org.uk/artists/francisco-de-goya","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Francisco de Goya (1746–1828) and the Spanish Enlightenment」","url":"https://www.metmuseum.org/toah/hd/goya/hd_goya.htm","accessed":"2026-11-08"}]},
  {"id":"tl-velazquez","artist":"velazquez","events":[{"year":1599,"when":"1599年","kind":"life","title":"セビリアで生まれる","detail":"南スペインの都市セビリアに生まれた。","src":[1]},{"year":1611,"when":"1611年","kind":"life","title":"画家パチェーコのもとで修業を始める","detail":"メトロポリタン美術館によると、画家パチェーコのもとで6年間の徒弟修業を始めた。","src":[2]},{"year":1617,"when":"1617年","kind":"life","title":"修業を終え、自分の工房を持つ","detail":"徒弟修業を終え、自分の工房を開く資格を得た。","src":[1]},{"year":1623,"when":"1623年","kind":"life","title":"フェリペ4世の宮廷画家になる","detail":"若い国王の肖像を描くよう求められ、気に入られて宮廷画家に任命された。","src":[1,2]},{"year":1629,"when":"1629〜1631年","kind":"life","title":"最初のイタリア旅行","detail":"メトロポリタン美術館によると、1629年6月から1631年1月までイタリアを旅した。","src":[1,2]},{"year":1649,"when":"1649〜1651年","kind":"life","title":"2度目のイタリア旅行","detail":"メトロポリタン美術館によると、王のため美術品を集める旅で、教皇インノケンティウス10世の肖像を描いた。","src":[1,2]},{"year":1658,"when":"1658年","kind":"life","title":"サンティアゴ騎士団の騎士になる","detail":"ずっと望んでいた名誉だった。『ラス・メニーナス』の自画像には騎士の印が描き足されている。","src":[1]},{"year":1660,"when":"1660年","kind":"life","title":"病気になって亡くなる","detail":"この年に病気になって亡くなり、妻もその1週間後に亡くなった。","src":[1]},{"year":1808,"when":"1808〜1814年","kind":"world","title":"ナポレオンの半島戦争（1808〜1814年）","detail":"メトロポリタン美術館によると、この戦争の混乱で、ベラスケスの作品の一部が北ヨーロッパに散らばった。","src":[2]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Diego Velázquez」","url":"https://www.nationalgallery.org.uk/artists/diego-velazquez","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Velázquez (1599–1660)」","url":"https://www.metmuseum.org/essays/velazquez-1599-1660","accessed":"2026-11-08"}]},
  {"id":"tl-pissarro","artist":"pissarro","events":[{"year":1830,"when":"1830年","kind":"life","title":"セント・トーマス島で生まれる","detail":"ロンドンのナショナル・ギャラリーによると、当時デンマーク領だった西インド諸島のセント・トーマスの生まれ。","src":[1,2]},{"year":1856,"when":"1856年","kind":"work","title":"『セント・トーマスの入り江』を描く","detail":"ワシントンのナショナル・ギャラリー・オブ・アートの画家ページに、1856年の作品として載っている。","src":[1]},{"year":1870,"when":"1870〜1871年","kind":"life","title":"ロンドンを訪れる","detail":"ロンドンのナショナル・ギャラリーによると、1870〜71年にロンドンを訪れた。","src":[2]},{"year":1870,"when":"1870〜1871年","kind":"world","title":"普仏戦争が起こる","detail":"メトロポリタン美術館のサイトにあるエッセイによると、普仏戦争は1870〜71年。そのなかでパリ包囲戦もあった。","src":[3]},{"year":1874,"when":"1874年","kind":"work","title":"パリで展覧会を開いた会の創立メンバー","detail":"メトロポリタン美術館のサイトにあるエッセイによると、1874年にパリで展覧会を開き、印象派と呼ばれる動きの始まりとなった会の創立メンバーの一人。","src":[3]},{"year":1886,"when":"1886年","kind":"work","title":"最後の独立展にスーラらを推す","detail":"メトロポリタン美術館のサイトにあるエッセイによると、1886年の最後の展覧会で、スーラとシニャックの参加を後押しした。","src":[3]},{"year":1897,"when":"1897年","kind":"work","title":"『イタリア大通り、朝、日光』を描く","detail":"ワシントンのナショナル・ギャラリー・オブ・アートの画家ページに、1897年の作品として載っている。","src":[1]},{"year":1903,"when":"1903年","kind":"life","title":"亡くなる","detail":"ワシントンとロンドンのナショナル・ギャラリーの画家ページは、生没年を1830〜1903年としている。","src":[1,2]}],"sources":[{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「Camille Pissarro」","url":"https://www.nga.gov/artists/1791-camille-pissarro","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「Camille Pissarro (1830 - 1903)」","url":"https://www.nationalgallery.org.uk/artists/camille-pissarro","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Impressionism: Art and Modernity」（外部筆者 Margaret Samu のエッセイ）","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity","accessed":"2026-11-08"}]},
  {"id":"tl-sisley","artist":"sisley","events":[{"year":1839,"when":"1839年","kind":"life","title":"パリで生まれる","detail":"ロンドンのナショナル・ギャラリーとテートによると、イギリス人の両親のもと、パリで生まれた。","src":[1,2]},{"year":1862,"when":"1862年","kind":"life","title":"グレールのアトリエに入る","detail":"テートによると、1862年にグレールのアトリエに入り、ルノワール、モネ、バジールと出会った。","src":[1]},{"year":1870,"when":"1870〜1871年","kind":"world","title":"普仏戦争が起こる","detail":"メトロポリタン美術館のサイトにあるエッセイによると、普仏戦争は1870〜71年。そのなかでパリ包囲戦もあった。","src":[3]},{"year":1871,"when":"1871年","kind":"life","title":"父の援助がなくなる","detail":"テートによると、1871年から父に支えてもらえなくなり、生涯の多くを貧しく過ごした。","src":[1]},{"year":1874,"when":"1874年","kind":"work","title":"印象派の展覧会に出品する","detail":"テートによると、1874年に印象派の展覧会に出した。ほかに1876・1877・1882年にも出している。","src":[1]},{"year":1878,"when":"1878年","kind":"work","title":"『栗並木の道』を描く","detail":"メトロポリタン美術館のサイトにあるエッセイは、1878年の作品として取り上げ、くだけて見えて構図は丁寧に組まれていると述べる。","src":[3]},{"year":1880,"when":"1880年","kind":"life","title":"モレ＝シュル＝ロワン近くに落ち着く","detail":"テートによると、1880年にモレ＝シュル＝ロワン近くに落ち着き、晩年作の多くをそこで描いた。","src":[1]},{"year":1883,"when":"1883年","kind":"work","title":"初の個展をパリで開く","detail":"テートによると、1883年にパリのラ・ヴィ・モデルヌで初めての個展を開いた。","src":[1]},{"year":1899,"when":"1899年","kind":"life","title":"亡くなる","detail":"テートによると、モレ＝シュル＝ロワンで亡くなった。ロンドンのナショナル・ギャラリーも生没年を1839〜1899年とする。","src":[1,2]}],"sources":[{"name":"テート「Alfred Sisley 1839–1899」","url":"https://www.tate.org.uk/art/artists/alfred-sisley-1948","accessed":"2026-11-08"},{"name":"ロンドン・ナショナル・ギャラリー「Alfred Sisley (1839 - 1899)」","url":"https://www.nationalgallery.org.uk/artists/alfred-sisley","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Impressionism: Art and Modernity」（外部筆者 Margaret Samu のエッセイ）","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity","accessed":"2026-11-08"}]},
  {"id":"tl-cassatt","artist":"cassatt","events":[{"year":1844,"when":"1844年","kind":"life","title":"ペンシルベニアの名家に生まれる","detail":"スミソニアン・アメリカ美術館によると、ペンシルベニア州の名の通った家に1844年に生まれ、芸術家としての日々はヨーロッパで過ごした。","src":[1]},{"year":1868,"when":"1868年","kind":"work","title":"パリのサロンへの出品を始める","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、1868年から、毎年のパリのサロンに定期的に出品した。","src":[2]},{"year":1878,"when":"1878年","kind":"work","title":"劇場の場面を描く","detail":"メトロポリタン美術館のサイトにあるエッセイは、1878年の『ロージュにて』を、劇場の楽しみを描いた例に挙げている。","src":[3]},{"year":1879,"when":"1879年ごろ","kind":"work","title":"初めての版画をつくる","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、1879年ごろ、ドガのそばで最初の版画をつくった。","src":[2]},{"year":1880,"when":"1880年","kind":"work","title":"第5回印象派展に版画を出す","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、1880年の第5回印象派展に版画を出した。ドガとピサロも出している。","src":[2]},{"year":1890,"when":"1890年春","kind":"world","title":"パリで日本の木版画の大展覧会","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、1890年春、日本の木版画の大きな展覧会がパリの美術界をにぎわせた。","src":[2]},{"year":1890,"when":"1890〜1891年","kind":"work","title":"カラー版画の連作10点をつくる","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、日本の木版画の鮮やかな色や平らな形、強い線を取り入れた10点組。","src":[2]},{"year":1893,"when":"1893年","kind":"work","title":"初の回顧展を開く","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、1893年の初の回顧展には版画だけで67点が並んだ。","src":[2]},{"year":1926,"when":"1926年","kind":"life","title":"亡くなる","detail":"スミソニアン・アメリカ美術館の画家ページは、没年を1926年としている。","src":[1]}],"sources":[{"name":"スミソニアン・アメリカ美術館「Mary Cassatt」","url":"https://americanart.si.edu/artist/mary-cassatt-770","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「Mary Cassatt, the Daring Printmaker」","url":"https://www.nga.gov/stories/articles/mary-cassatt-daring-printmaker","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Impressionism: Art and Modernity」（外部筆者 Margaret Samu のエッセイ）","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity","accessed":"2026-11-08"}]},
  {"id":"tl-ingres","artist":"ingres","events":[{"year":1780,"when":"1780年","kind":"life","title":"モントーバンで生まれる","detail":"オルセー美術館の記録では、1780年にフランスのモントーバンで生まれた。","src":[2,1]},{"year":1801,"when":"1801年","kind":"life","title":"ローマ留学の奨学金を得る","detail":"ロンドンのナショナル・ギャラリーによると、この年にローマへの奨学金を得た。","src":[1]},{"year":1804,"when":"1804年","kind":"world","title":"ナポレオンの戴冠式が行われる","detail":"ルーヴル美術館の記録で、1804年12月2日にパリのノートルダム大聖堂で行われたと示されている。","src":[5]},{"year":1806,"when":"1806年","kind":"life","title":"奨学金でローマへ向かう","detail":"奨学金を得たのは1801年で、実際にローマへ行ったのは1806年だった。","src":[1]},{"year":1814,"when":"1814年","kind":"work","title":"『グランド・オダリスク』を描く","detail":"ルーヴル美術館の記録では、1814年の日付とローマの署名がある。ナポリ王妃カロリーヌ・ミュラのために描かれた。","src":[3]},{"year":1820,"when":"1820年ごろ","kind":"work","title":"『泉』にとりかかる","detail":"オルセー美術館によると、この絵は1820年ごろに描き始められ、完成は1856年だった。","src":[2]},{"year":1851,"when":"1851年","kind":"work","title":"『モワテシエ夫人』を描く","detail":"ワシントンのナショナル・ギャラリー・オブ・アートの解説では、細部まで実物を見て描くことにこだわった。","src":[4]},{"year":1856,"when":"1856年","kind":"work","title":"『泉』が完成する","detail":"オルセー美術館によると、弟子のバルゼとデゴフが、小物と背景の仕上げを手伝った。","src":[2]},{"year":1867,"when":"1867年","kind":"life","title":"パリで亡くなる","detail":"オルセー美術館の記録では、1867年にパリで亡くなった。","src":[2,1]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Jean-Auguste-Dominique Ingres」","url":"https://www.nationalgallery.org.uk/artists/jean-auguste-dominique-ingres","accessed":"2026-11-08"},{"name":"オルセー美術館「La Source」（Ingres）","url":"https://www.musee-orsay.fr/en/artworks/la-source-525","accessed":"2026-11-08"},{"name":"ルーヴル美術館コレクション「Une odalisque, dite La grande odalisque」","url":"https://collections.louvre.fr/en/ark:/53355/cl010065566","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「Madame Moitessier」","url":"https://www.nga.gov/artworks/32696-madame-moitessier","accessed":"2026-11-08"},{"name":"ルーヴル美術館コレクション「Le Couronnement de l\u0027empereur Napoléon Ier et de l\u0027impératrice Joséphine」","url":"https://collections.louvre.fr/en/ark:/53355/cl010065720","accessed":"2026-11-08"}]},
  {"id":"tl-david","artist":"david","events":[{"year":1748,"when":"1748年","kind":"life","title":"パリで生まれる","detail":"ロンドンのナショナル・ギャラリーとルーヴル美術館の記録で、パリ生まれで1748年生まれとされている。","src":[1,2]},{"year":1775,"when":"1775〜1780年","kind":"life","title":"ローマで過ごす","detail":"ナショナル・ギャラリーによると、1775年から1780年をローマで過ごし、1784〜85年にも戻った。","src":[1]},{"year":1785,"when":"1785年","kind":"work","title":"『ホラティウス兄弟の誓い』","detail":"ナショナル・ギャラリーによると、ルーヴルにあるこの作品は、構図も主題も簡潔で厳しい点が目立つ。","src":[1]},{"year":1789,"when":"1789年","kind":"world","title":"フランスの1789年の革命","detail":"ナショナル・ギャラリーによると、ダヴィッドはこの革命に積極的に加わり、議員に選ばれた。","src":[1]},{"year":1793,"when":"1793年","kind":"work","title":"『暗殺されたマラー』を描く","detail":"ブリュッセルのベルギー王立美術館が所蔵する油彩で、1793年の作として記録されている。","src":[3]},{"year":1804,"when":"1804年","kind":"world","title":"ナポレオンの戴冠の儀式","detail":"ルーヴル美術館の記録では、1804年12月2日から5日にパリで戴冠に関する儀式が行われた。","src":[2]},{"year":1807,"when":"1807年末","kind":"work","title":"戴冠を描いた大作が完成","detail":"ルーヴル美術館の記録では、ナポレオンが注文した大作で、1807年の終わりに完成した。","src":[2]},{"year":1812,"when":"1812年","kind":"work","title":"書斎のナポレオンを描く","detail":"ワシントンのナショナル・ギャラリー・オブ・アートによると、民法典の起草に夜通し取り組んだ明け方の姿を描いた。","src":[4]},{"year":1815,"when":"1815年以降","kind":"life","title":"ナポレオン敗北後、ブリュッセルで制作","detail":"ナショナル・ギャラリーによると、ナポレオンの最終的な敗北は1815年で、その後は亡命先のブリュッセルで描いた。","src":[1]},{"year":1825,"when":"1825年","kind":"life","title":"ブリュッセルで亡くなる","detail":"ナショナル・ギャラリーやルーヴル美術館の記録で、1825年にブリュッセルで亡くなったとされている。","src":[1,2,3]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Jacques-Louis David」","url":"https://www.nationalgallery.org.uk/artists/jacques-louis-david","accessed":"2026-11-08"},{"name":"ルーヴル美術館コレクション「Le Couronnement de l\u0027empereur Napoléon Ier et de l\u0027impératrice Joséphine」","url":"https://collections.louvre.fr/en/ark:/53355/cl010065720","accessed":"2026-11-08"},{"name":"ベルギー王立美術館「Marat assassiné」（Jacques-Louis David）","url":"https://fine-arts-museum.be/fr/la-collection/jacques-louis-david-marat-assassine","accessed":"2026-11-08"},{"name":"ナショナル・ギャラリー・オブ・アート（ワシントン）「The Emperor Napoleon in His Study at the Tuileries」","url":"https://www.nga.gov/artworks/46114-emperor-napoleon-his-study-tuileries","accessed":"2026-11-08"}]},
  {"id":"tl-corot","artist":"corot","events":[{"year":1796,"when":"1796年","kind":"life","title":"パリで生まれる","detail":"ナショナル・ギャラリーによると、1796年に布商人と婦人帽子商の子として生まれた。","src":[1,3]},{"year":1825,"when":"1825〜1828年","kind":"life","title":"最初のイタリア旅行をする","detail":"ナショナル・ギャラリーによると、ローマとその周辺の田園で過ごし、ナポリにも足を延ばした。","src":[1,3]},{"year":1827,"when":"1827年","kind":"work","title":"サロンに初めて作品を送る","detail":"ナショナル・ギャラリーによると、『ナルニの眺め』と『ローマ近郊の平野』の2点を送った。","src":[1]},{"year":1835,"when":"1835年","kind":"work","title":"『荒野のハガル』をサロンに出す","detail":"ナショナル・ギャラリーによると、初期の作風を示す作品として挙げられている。","src":[1]},{"year":1855,"when":"1855年","kind":"work","title":"万博で金メダルを得る","detail":"ナショナル・ギャラリーによると、1855年の万国博覧会に6点を出し、金メダルを受けた。","src":[1]},{"year":1855,"when":"1855年","kind":"world","title":"万国博覧会が開かれる","detail":"ナショナル・ギャラリーのコロー紹介が、1855年の万国博覧会に触れている。","src":[1]},{"year":1864,"when":"1864年","kind":"work","title":"『モルトフォンテーヌの思い出』が買われる","detail":"ルーヴル美術館の記録では、この絵は1864年のサロンでナポレオン3世の資金により購入された。","src":[2]},{"year":1871,"when":"1871年","kind":"life","title":"フランス北東部へ旅する","detail":"ナショナル・ギャラリーによると、1871年のコミューンの時期に、フランス北東部へ旅した。","src":[1]},{"year":1875,"when":"1875年","kind":"life","title":"亡くなる","detail":"ナショナル・ギャラリーでは1875年没。メトロポリタン美術館によると、パリで亡くなった。","src":[1,3]}],"sources":[{"name":"ロンドン・ナショナル・ギャラリー「Camille Corot (1796 - 1875)」","url":"https://www.nationalgallery.org.uk/artists/camille-corot","accessed":"2026-11-08"},{"name":"ルーヴル美術館コレクション「Souvenir de Mortefontaine (Oise).」","url":"https://collections.louvre.fr/en/ark:/53355/cl010066968","accessed":"2026-11-08"},{"name":"メトロポリタン美術館「Italian Landscape」（Camille Corot）","url":"https://www.metmuseum.org/art/collection/search/435973","accessed":"2026-11-08"}]},
  {"id":"tl-hokusai","artist":"hokusai","events":[{"year":1760,"when":"1760年","kind":"life","title":"墨田区に生まれる","detail":"生まれた土地を含む一帯は武蔵国葛飾郡で、「葛飾」の名はそこから取ったといわれる。","src":[1,2]},{"year":1809,"when":"1809年ごろ","kind":"life","title":"卍などの号を名乗り川柳も詠む","detail":"北斎の句は川柳の句集『誹風柳多留』に収められていて、そこでの号には卍や万字がある。","src":[1]},{"year":1814,"when":"1814年","kind":"work","title":"『北斎漫画』の初編を出す","detail":"全十五編になる絵手本（絵の見本帳）の最初の1冊。シリーズの図は合わせて約3900で、人や自然、神仏妖怪などが描かれている。","src":[3]},{"year":1831,"when":"1831年ごろ","kind":"work","title":"『冨嶽三十六景』の『神奈川沖浪裏』","detail":"大判の錦絵。『冨嶽三十六景』は晩年の錦絵の代表作で、同じ対象の見え方の変化に目を向けたシリーズ。","src":[1]},{"year":1834,"when":"1834年","kind":"work","title":"絵手本『富嶽百景』初編を出す","detail":"75歳の時の出版。巻末の跋文に、90歳で絵の奥意を極め、100歳で神妙の域に達するだろうと書いている。","src":[1]},{"year":1849,"when":"1849年","kind":"life","title":"約90年の生涯を終える","detail":"死の直前に、あと5年生きられれば本物の絵師になれると語ったといわれる。","src":[1,2]},{"year":1867,"when":"1867年","kind":"world","title":"パリ万国博覧会が開かれる","detail":"すみだ北斎美術館は、この博覧会で浮世絵が紹介されジャポニスム（日本趣味）が起こったと説明する。外務省外交史料館の事例によると、幕府の使節団が浮世絵なども出品した。","src":[1,4]}],"sources":[{"name":"すみだ北斎美術館「北斎について」","url":"https://hokusai-museum.jp/modules/Page/pages/view/401","accessed":"2026-11-08"},{"name":"メトロポリタン美術館 作品ページ「Under the Wave off Kanagawa」","url":"https://www.metmuseum.org/art/collection/search/45434","accessed":"2026-11-08"},{"name":"すみだ北斎美術館 収蔵作品「北斎漫画 初編」","url":"https://hokusai-museum.jp/modules/Collection/collections/view/93?lang=ja","accessed":"2026-11-08"},{"name":"レファレンス協同データベース（提供館: 外務省外交史料館）「1867年（慶応3年）開催のパリ万国博覧会に、日本が出品したことを示す記録はありますか。」","url":"https://crd.ndl.go.jp/reference/entry/index.php?page=ref_view\u0026id=1000075585","accessed":"2026-11-08"}]},
  {"id":"tl-hiroshige","artist":"hiroshige","events":[{"year":1797,"when":"1797年","kind":"life","title":"江戸に生まれる","detail":"父は江戸八重洲河岸の定火消同心で、広重はその長男として生まれた。","src":[1,2]},{"year":1809,"when":"1809年","kind":"life","title":"13歳で火消の家業を継ぐ","detail":"この年、父と母が続けて亡くなっている。","src":[1]},{"year":1811,"when":"1811年ごろ","kind":"life","title":"歌川豊広に弟子入りする","detail":"入門先は浮世絵師の歌川豊広。絵好きは子どものころからだった。","src":[1]},{"year":1833,"when":"1833年ごろ","kind":"work","title":"『東海道五拾三次之内』を刊行","detail":"題材は東海道の宿場やその近くの風景で、保永堂版と呼ばれる。旅がはやっていた時代によく売れ、広重は人気絵師の仲間に加わった。","src":[1]},{"year":1857,"when":"1857年","kind":"work","title":"『名所江戸百景』の大橋の夕立の図","detail":"ゴッホ美術館の作品情報では、大橋に夕立が降る場面を描いたこの版画を1857年としている。","src":[3]},{"year":1858,"when":"1858年","kind":"work","title":"『名所江戸百景』の『両国花火』","detail":"メトロポリタン美術館によると、この版画は1858年の作。","src":[2]},{"year":1858,"when":"1858年","kind":"life","title":"『名所江戸百景』の制作中に亡くなる","detail":"62歳だった。『名所江戸百景』は最晩年の傑作とされている。","src":[1,2]},{"year":1887,"when":"1887年","kind":"world","title":"ゴッホが広重の版画を油彩で写す","detail":"ゴッホ美術館によると、パリで広重の版画をもとに橋と雨の絵を描いた。色は元の版画より強くしている。","src":[3]}],"sources":[{"name":"静岡市東海道広重美術館「歌川広重と浮世絵」","url":"https://tokaido-hiroshige.jp/outline/utagawa-hiroshige.html","accessed":"2026-11-08"},{"name":"メトロポリタン美術館 作品ページ「Fireworks at Ryōgoku Bridge, from the series One Hundred Famous Views of Edo」","url":"https://www.metmuseum.org/art/collection/search/37093","accessed":"2026-11-08"},{"name":"ゴッホ美術館 作品ページ「Bridge in the Rain (after Hiroshige)」","url":"https://www.vangoghmuseum.nl/en/collection/s0114V1962","accessed":"2026-11-08"}]}
];
